import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[n];
        int max = 0;

        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
            if (a[i] > max) max = a[i];
        }

        int ans = 0;

        for (int h = 1; h < max; h++) {
            boolean inComponent = false;
            for (int i = 0; i < n; i++) {
                if (a[i] <= h) {
                    if (!inComponent) {
                        ans++;
                        inComponent = true;
                    }
                } else {
                    inComponent = false;
                }
            }
        }

        System.out.println(ans);
    }
}
